<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';import {pmsApi} from './api';import PmsTaskDetail from './PmsTaskDetail.vue';import PmsSprintBoard from './PmsSprintBoard.vue';import PmsFormDialog from './PmsFormDialog.vue';import PmsDescriptionEditor from './PmsDescriptionEditor.vue';
const props=defineProps<{csrf?:string;permissions:string[];initialDepartment?:number|null}>();const dragged=ref<number|null>(null),data=ref<any>(null),board=ref<any>(null),department=ref<any>(null),project=ref(''),workflow=ref(''),sprint=ref('all'),issue=ref<number|null>(null),issueAction=ref(''),busy=ref(false),error=ref(''),task=ref<any>(null);
async function open(d:any){department.value=d;busy.value=true;try{board.value=(await pmsApi('team-space/'+d.id+'?'+new URLSearchParams({project:project.value,workflow:workflow.value,sprint:sprint.value}))).data;error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function drop(c:any){if(!dragged.value||busy.value)return;const id=dragged.value;dragged.value=null;busy.value=true;try{await pmsApi('tasks/'+id+'/board',props.csrf,'PATCH',{workflow_id:board.value.selectedWorkflow.id,workflow_column_id:c.id});await open(department.value);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function showIssue(id:number,action=''){issue.value=id;issueAction.value=action;}
function newTask(){task.value={title:'',description:'',project_id:Number(project.value)||'',workflow_id:board.value.selectedWorkflow?.id,workflow_column_id:board.value.selectedWorkflow?.columns[0]?.id,status:'pending',priority:1,sprint_id:'',assignee_ids:[],due_date:'',attachments:[]};}
async function create(values:any,done:()=>void){busy.value=true;try{const f=new FormData();for(const [key,value] of Object.entries(values)){if(Array.isArray(value))value.forEach(v=>f.append(key+'[]',v instanceof File?v:String(v)));else if(value!==''&&value!=null)f.append(key,String(value));}await pmsApi('tasks',props.csrf,'POST',f);done();await open(department.value);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function quickCreate(title:string,done:()=>void,projectId:string){if(!projectId){error.value='Select a department project first.';return;}await create({title,project_id:projectId,workflow_id:board.value.selectedWorkflow?.id,workflow_column_id:board.value.selectedWorkflow?.columns[0]?.id,status:'pending'},done);}
function liveUpdate(){if(!busy.value&&!task.value&&board.value&&department.value)void open(department.value);}onMounted(async()=>{window.addEventListener('pms:changed',liveUpdate);try{data.value=await pmsApi('team-space');const q=new URLSearchParams(location.search);project.value=q.get('project')||'';sprint.value=q.get('sprint')||'all';const selected=data.value.departments.find((d:any)=>d.id===(props.initialDepartment||Number(q.get('department'))));if(selected)await open(selected);const id=Number(q.get('issue'));if(id>0)issue.value=id;}catch(e){error.value=(e as Error).message;}});onUnmounted(()=>window.removeEventListener('pms:changed',liveUpdate));
</script>
<template><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><template v-if="!board"><h3>Team Space</h3><div class="row g-3 my-3"><div v-for="d in data?.departments" :key="d.id" class="col-xl-6"><div class="card"><div class="card-body"><div class="admin-section-heading"><h5>{{d.dept_name}}</h5><button class="button primary" @click="open(d)">Open board</button></div><p v-if="!d.projects.length" class="text-muted">Department backlog</p><a v-for="p in d.projects" :key="p.id" class="pms-deadline-row" :href="'/pms?section=project-board&project='+p.id">{{p.name}}</a></div></div></div><div v-if="data?.otherProjects.length" class="col-12"><div class="card p-4"><h5>Other projects</h5><a v-for="p in data.otherProjects" :key="p.id" class="pms-deadline-row" :href="'/pms?section=project-board&project='+p.id">{{p.name}}</a></div></div></div></template><template v-else><PmsSprintBoard v-if="board.workflows" :data="board" :department="department" :permissions="permissions" :busy="busy" :project-filter="project" :workflow-filter="workflow" :sprint-filter="sprint" @project="project=$event;open(department)" @workflow="workflow=$event;open(department)" @sprint="sprint=$event;open(department)" @create="newTask" @quick-create="quickCreate" @open="showIssue($event)" @edit="showIssue($event,'edit')" @assign="showIssue($event,'assign')" @handoff="showIssue($event,'handoff')" @place="showIssue($event,'place')" @delete="showIssue($event,'delete')" @drag="dragged=$event" @drop="drop($event)"/><div v-else class="card p-4"><h3>{{department.dept_name}}</h3><p>This department has no projects or backlog tasks yet.</p></div><button class="button mt-3" @click="board=null">Back to Team Space</button></template><PmsFormDialog v-if="task" title="Create issue" wide @close="task=null"><form class="pms-reference-form" @submit.prevent="create(task,()=>task=null)"><label class="full-width">Project <span class="text-danger">*</span><select v-model="task.project_id" required><option value="">Choose a department project</option><option v-for="p in board.departmentProjects" :key="p.id" :value="p.id">{{p.name}}</option></select><small>The new task will belong to the selected project.</small></label><label class="full-width">Summary<input v-model="task.title" required maxlength="255"></label><label class="full-width">Description<PmsDescriptionEditor v-model="task.description"/></label><label>Workflow column<select v-model="task.workflow_column_id"><option v-for="c in board.selectedWorkflow.columns" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Priority<select v-model="task.priority"><option v-for="(label,i) in ['Low','Normal','High','Urgent']" :key="i" :value="i">{{label}}</option></select></label><label>Assignees<select v-model="task.assignee_ids" multiple size="4"><option v-for="p in board.asignee" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Sprint<select v-model="task.sprint_id"><option value="">Backlog</option><option v-for="s in board.sprints?.filter((s:any)=>s.project_id==task.project_id)" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Due date<input v-model="task.due_date" type="datetime-local"></label><label>Attachments<input type="file" multiple @change="task.attachments=Array.from(($event.target as HTMLInputElement).files||[])"></label><div class="editor-actions"><button class="button" type="button" @click="task=null">Cancel</button><button class="button primary" :disabled="busy">Create issue</button></div></form></PmsFormDialog><PmsTaskDetail v-if="issue" :id="issue" :initial-action="issueAction" :csrf="csrf" :permissions="permissions" @close="issue=null;issueAction=''" @updated="open(department)"/></template>
